sp_widget.client_script:
api.controller=function() {
    var c = this;

    c.menuOpen = false;

    c.closeMenu = function() {
        c.menuOpen = false;
    };
}

sp_widget.css:
.cfa-navbar{
  background:#0f172a;
  color:#fff;
  position:sticky;
  top:0;
  z-index:20;
  border-bottom:1px solid #1e293b;
}
.cfa-navbar-inner{
  max-width:1200px;
  margin:0 auto;
  padding:14px 24px;
  display:flex;
  align-items:center;
  justify-content:space-between;
}
.cfa-brand{
  font-weight:800;
  font-size:16px;
  display:flex;
  align-items:center;
  gap:8px;
}
.cfa-brand b{ color:#2dd4bf; }
.cfa-logo{ font-size:20px; }

.cfa-nav-links{
  display:flex;
  gap:28px;
}
.cfa-nav-links a{
  color:#cbd5e1;
  text-decoration:none;
  font-size:14px;
  font-weight:600;
  transition:.15s;
}
.cfa-nav-links a:hover{ color:#fff; }

.cfa-nav-actions{
  display:flex;
  align-items:center;
  gap:12px;
}
.cfa-login-btn{
  background:#0d9488;
  color:#fff;
  padding:8px 18px;
  border-radius:8px;
  font-size:13.5px;
  font-weight:700;
  text-decoration:none;
}
.cfa-login-btn:hover{ background:#0f766e; }

.cfa-menu-toggle{
  display:none;
  background:none;
  border:none;
  color:#fff;
  font-size:20px;
  cursor:pointer;
}

@media(max-width:768px){
  .cfa-nav-links{
    display:none;
    position:absolute;
    top:100%;
    left:0;
    right:0;
    background:#0f172a;
    flex-direction:column;
    padding:16px 24px;
    gap:16px;
    border-bottom:1px solid #1e293b;
  }
  .cfa-nav-links.open{ display:flex; }
  .cfa-menu-toggle{ display:block; }
}

sp_widget.script:
(function() {

    // Native Service Portal login URL
    data.loginUrl = '/sp?id=login';

    // Check whether the current user is logged in
    data.isLoggedIn = !gs.getUser().isGuest();

})();
